-- HRIS contract/activation sync foundation. SOURCE ONLY; not auto-applied by deployment.
ALTER TABLE public.employee_contracts ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'hris', ADD COLUMN IF NOT EXISTS smart_office_code text, ADD COLUMN IF NOT EXISTS smart_office_document_id text, ADD COLUMN IF NOT EXISTS payload_snapshot jsonb, ADD COLUMN IF NOT EXISTS validation_status text NOT NULL DEFAULT 'pending', ADD COLUMN IF NOT EXISTS validated_at timestamptz, ADD COLUMN IF NOT EXISTS validated_by uuid REFERENCES public.user_profiles(id) ON DELETE SET NULL;
ALTER TABLE public.employees ADD COLUMN IF NOT EXISTS activation_state text NOT NULL DEFAULT 'inactive', ADD COLUMN IF NOT EXISTS activation_ready boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS activated_at timestamptz, ADD COLUMN IF NOT EXISTS activated_by uuid REFERENCES public.user_profiles(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS activation_contract_id uuid REFERENCES public.employee_contracts(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS last_module_sync_at timestamptz;
CREATE TABLE IF NOT EXISTS public.employee_sync_outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,employee_id text NOT NULL,event_type text NOT NULL,role text,branch text,branch_id uuid REFERENCES public.branches(id) ON DELETE SET NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'pending',module_status jsonb NOT NULL DEFAULT '{}'::jsonb,attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS employee_contracts_document_number_uq ON public.employee_contracts(document_number) WHERE document_number IS NOT NULL AND trim(document_number)<>'';
CREATE OR REPLACE FUNCTION public.hris_sync_smart_office_contract(p_employee_id text,p_contract_type text,p_document_number text,p_gdoc_url text,p_pdf_url text,p_start_date date,p_end_date date,p_payload jsonb DEFAULT '{}'::jsonb,p_document_id text DEFAULT NULL) RETURNS public.employee_contracts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.employee_contracts; BEGIN IF NOT EXISTS(SELECT 1 FROM public.employees WHERE employee_id=p_employee_id) THEN RAISE EXCEPTION 'employee_not_found'; END IF; INSERT INTO public.employee_contracts(employee_id,contract_type,document_number,gdoc_url,pdf_url,start_date,end_date,status,source,smart_office_code,smart_office_document_id,payload_snapshot,validation_status,updated_at) VALUES(p_employee_id,COALESCE(NULLIF(p_contract_type,''),'PKWT'),NULLIF(trim(p_document_number),''),NULLIF(trim(p_gdoc_url),''),NULLIF(trim(p_pdf_url),''),p_start_date,p_end_date,'DRAFT','smart_office','PKWT',NULLIF(trim(p_document_id),''),COALESCE(p_payload,'{}'::jsonb),'pending',now()) ON CONFLICT(document_number) WHERE document_number IS NOT NULL AND trim(document_number)<>'' DO UPDATE SET employee_id=EXCLUDED.employee_id,contract_type=EXCLUDED.contract_type,gdoc_url=EXCLUDED.gdoc_url,pdf_url=EXCLUDED.pdf_url,start_date=EXCLUDED.start_date,end_date=EXCLUDED.end_date,source='smart_office',payload_snapshot=EXCLUDED.payload_snapshot,updated_at=now() RETURNING * INTO v; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.hris_validate_contract(p_contract_id uuid) RETURNS public.employee_contracts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r text; v public.employee_contracts; BEGIN r=lower(public.get_my_role()); IF r NOT IN('admin','direksi','direktur') THEN RAISE EXCEPTION 'write_permission_required'; END IF; UPDATE public.employee_contracts SET validation_status='validated',status='AKTIF',validated_at=now(),validated_by=auth.uid(),updated_at=now() WHERE id=p_contract_id RETURNING * INTO v; IF NOT FOUND THEN RAISE EXCEPTION 'contract_not_found'; END IF; UPDATE public.employees SET activation_ready=true,activation_state=CASE WHEN activation_state='active' THEN 'active' ELSE 'ready' END,activation_contract_id=v.id,updated_at=now() WHERE employee_id=v.employee_id; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.hris_activate_employee(p_employee_id text) RETURNS public.employees LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r text; e public.employees; c public.employee_contracts; BEGIN r=lower(public.get_my_role()); IF r NOT IN('admin','direksi','direktur') THEN RAISE EXCEPTION 'write_permission_required'; END IF; SELECT * INTO e FROM public.employees WHERE employee_id=p_employee_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'employee_not_found'; END IF; SELECT * INTO c FROM public.employee_contracts WHERE employee_id=p_employee_id AND validation_status='validated' AND status='AKTIF' AND(start_date IS NULL OR start_date<=current_date) AND(end_date IS NULL OR end_date>=current_date) ORDER BY start_date DESC NULLS LAST,updated_at DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'validated_active_contract_required'; END IF; UPDATE public.employees SET status='AKTIF',activation_state='active',activation_ready=true,activated_at=now(),activated_by=auth.uid(),activation_contract_id=c.id,updated_at=now() WHERE employee_id=p_employee_id RETURNING * INTO e; INSERT INTO public.employee_sync_outbox(employee_id,event_type,role,branch,payload) VALUES(e.employee_id,'employee_activated',lower(coalesce(e.position,'')),e.branch,to_jsonb(e)); RETURN e; END $$;
CREATE OR REPLACE VIEW public.hris_contract_employee_view WITH(security_invoker=true) AS SELECT c.id,c.employee_id,e.full_name,e.position,e.department,e.branch,e.salary_base,e.status AS employee_status,e.activation_state,e.activation_ready,c.contract_type,c.start_date,c.end_date,c.document_number,c.gdoc_url,c.pdf_url,c.status AS contract_status,c.validation_status,c.validated_at,c.source,c.updated_at FROM public.employee_contracts c LEFT JOIN public.employees e ON e.employee_id=c.employee_id;
GRANT SELECT ON public.hris_contract_employee_view TO authenticated; GRANT EXECUTE ON FUNCTION public.hris_validate_contract(uuid) TO authenticated; GRANT EXECUTE ON FUNCTION public.hris_activate_employee(text) TO authenticated; REVOKE ALL ON FUNCTION public.hris_sync_smart_office_contract(text,text,text,text,text,date,date,jsonb,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.hris_sync_smart_office_contract(text,text,text,text,text,date,date,jsonb,text) TO service_role;
